package com.oibsip.onlineexam.ui;
import javax.swing.*;import java.awt.*;import com.oibsip.onlineexam.model.*;import java.time.Duration;
public class ResultPanel extends JPanel {private final MainFrame f;private final JPanel rows=new JPanel();public ResultPanel(MainFrame x){f=x;setLayout(new BorderLayout(15,15));JLabel h=new JLabel("EXAM RESULT",SwingConstants.CENTER);h.setFont(new Font("SansSerif",Font.BOLD,28));add(h,BorderLayout.NORTH);rows.setLayout(new BoxLayout(rows,BoxLayout.Y_AXIS));add(new JScrollPane(rows),BorderLayout.CENTER);JButton logout=new JButton("Logout"),exit=new JButton("Exit Application");JPanel b=new JPanel();b.add(logout);b.add(exit);add(b,BorderLayout.SOUTH);logout.addActionListener(e->f.logout());exit.addActionListener(e->System.exit(0));}public void refresh(){rows.removeAll();ExamSession s=f.session().getExam();if(s==null||!s.isSubmitted())return;var r=f.exam().submit(s,s.isAutomatic());addLine("Student",f.session().getUser().getDisplayName());addLine("Exam", "Java Programming Assessment");addLine("Score",r.score()+" / "+r.total());addLine("Percentage",String.format("%.1f%%",r.percentage()));addLine("Correct",String.valueOf(r.correct()));addLine("Incorrect",String.valueOf(r.incorrect()));addLine("Unanswered",String.valueOf(r.unanswered()));addLine("Time Taken",format(r.timeTaken()));addLine("Submission",r.automatic()?"Automatic Submission (Time Expired)":"Manual Submission");JLabel br=new JLabel("Question-wise Breakdown");br.setFont(new Font("SansSerif",Font.BOLD,18));rows.add(Box.createVerticalStrut(15));rows.add(br);for(Question q:r.questions()){Character a=r.answers().get(q.id());String status=a==null?"Unanswered":a==q.correctAnswer()?"Correct":"Incorrect";rows.add(new JLabel("Q"+q.id()+" - "+status+" | Your Answer: "+(a==null?"Not Answered":a)+" | Correct Answer: "+q.correctAnswer()));}rows.revalidate();rows.repaint();}private void addLine(String a,String b){JLabel l=new JLabel(a+": "+b);l.setFont(new Font("SansSerif",Font.PLAIN,17));rows.add(l);rows.add(Box.createVerticalStrut(6));}private String format(Duration d){long s=d.getSeconds();return (s/60)+" minutes "+(s%60)+" seconds";}}
